import {
    BooleanColumn,
    GenericColumn,
    ReferenceColumn,
    StringColumn,
    Table,
    TranslatedTextColumn,
    UserRolesColumn,
} from '../../db'

export const sp_page = Table({
    name: 'sp_page',
    extends: 'sys_metadata',
    schema: {
        category: StringColumn({
            mandatory: false,
            label: 'Category',
            read_only: false,
            active: true,
            default: 'custom',
            maxLength: 40,
            dropdown: 'dropdown_without_none',
            choices: {
                kb: { label: 'Knowledge Base', sequence: 3, inactive: false, language: 'en' },
                sp_platform: { label: 'Service Portal Platform', sequence: 7, inactive: false, language: 'en' },
                sc: { label: 'Service Catalog', sequence: 4, inactive: false, language: 'en' },
                standard: { label: 'Standard', sequence: 1, inactive: false, language: 'en' },
                other: { label: 'Other Applications', sequence: 5, inactive: false, language: 'en' },
                sn_ex_sp_taxonomy: { label: 'Taxonomy', sequence: 8, inactive: false, language: 'en' },
                custom: { label: 'Custom', sequence: 2, inactive: false, language: 'en' },
                sample: { label: 'Sample', sequence: 6, inactive: false, language: 'en' },
            },
        }),
        css: GenericColumn({
            mandatory: false,
            label: 'Page Specific CSS',
            read_only: false,
            active: true,
            column_type: 'css',
        }),
        draft: BooleanColumn({ mandatory: false, label: 'Draft', read_only: false, active: true }),
        dynamic_title_structure: TranslatedTextColumn({
            mandatory: false,
            label: 'Dynamic page title',
            read_only: false,
            active: true,
        }),
        human_readable_url_structure: StringColumn({
            mandatory: false,
            label: 'Human readable url structure',
            read_only: false,
            active: true,
            maxLength: 100,
            dropdown: 'none',
        }),
        id: StringColumn({
            mandatory: true,
            label: 'ID',
            read_only: false,
            active: true,
            maxLength: 40,
            dropdown: 'none',
        }),
        internal: BooleanColumn({ mandatory: false, label: 'Internal', read_only: false, active: true }),
        omit_watcher: BooleanColumn({ mandatory: false, label: 'Omit watcher', read_only: false, active: true }),
        public: BooleanColumn({ mandatory: false, label: 'Public', read_only: false, active: true }),
        roles: UserRolesColumn({ mandatory: false, label: 'Roles', read_only: false, active: true }),
        seo_script: ReferenceColumn({
            mandatory: false,
            label: 'SEO script',
            read_only: false,
            active: true,
            referenceTable: 'sys_script_include',
        }),
        short_description: TranslatedTextColumn({
            mandatory: false,
            label: 'Short description',
            read_only: false,
            active: true,
        }),
        sys_id: GenericColumn({
            mandatory: false,
            label: 'Sys ID',
            read_only: false,
            active: true,
            column_type: 'GUID',
        }),
        title: TranslatedTextColumn({ mandatory: false, label: 'Title', read_only: false, active: true }),
        use_seo_script: BooleanColumn({ mandatory: false, label: 'Use SEO script', read_only: false, active: true }),
    },
})
